CREATE TABLE IF NOT EXISTS p(rowid REAL NOT NULL);
CREATE TABLE IF NOT EXISTS q(b TEXT UNIQUE);
SELECT * FROM p NATURAL JOIN p WHERE (WITH p AS (SELECT count(*) OVER () ORDER BY max(CURRENT_TIMESTAMP COLLATE BINARY) NOT IN (VALUES (CURRENT_DATE)) ASC NULLS LAST LIMIT FALSE) SELECT * FROM p WHERE CURRENT_TIME GROUP BY FALSE WINDOW w1 AS ()) NOT IN (CURRENT_TIME);